import { test, expect } from '@playwright/test';

test.describe('Element Manager - Add and Delete Elements', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
  });

  test('should add two elements when clicking Add Element button twice', async ({ page }) => {
    // Get the Add Element button
    const addButton = page.getByRole('button', { name: /add element/i });

    // Click the Add Element button twice
    await addButton.click();
    await addButton.click();

    // Verify that two delete buttons are created
    const deleteButtons = page.locator('.added-manually');
    await expect(deleteButtons).toHaveCount(2);
  });

  test('should delete one element when clicking a delete button, leaving exactly one', async ({ page }) => {
    // Get the Add Element button
    const addButton = page.getByRole('button', { name: /add element/i });

    // Click the Add Element button twice to create two delete buttons
    await addButton.click();
    await addButton.click();

    // Verify that two delete buttons exist
    const deleteButtons = page.locator('.added-manually');
    await expect(deleteButtons).toHaveCount(2);

    // Click the first delete button
    const firstDeleteButton = deleteButtons.first();
    await firstDeleteButton.click();

    // Verify that exactly one delete button remains
    await expect(deleteButtons).toHaveCount(1);
  });

  test('should handle multiple add and delete operations correctly', async ({ page }) => {
    const addButton = page.getByRole('button', { name: /add element/i });
    const deleteButtons = page.locator('.added-manually');

    // Add three elements
    await addButton.click();
    await addButton.click();
    await addButton.click();
    await expect(deleteButtons).toHaveCount(3);

    // Delete two elements
    await deleteButtons.first().click();
    await expect(deleteButtons).toHaveCount(2);

    await deleteButtons.first().click();
    await expect(deleteButtons).toHaveCount(1);

    // Add one more element
    await addButton.click();
    await expect(deleteButtons).toHaveCount(2);
  });
});
